import{_ as t,o,c as d,a6 as r}from"./chunks/framework.CCKCzdWs.js";const p=JSON.parse(`{"title":"Keyboard shortcuts","description":"Every keyboard shortcut the dashboard registers: the command palette, the assistant, the go-to chords, failure inbox triage, the test lists' search, the keys of the image and element viewers, and Piwi Picker's Runs window.","frontmatter":{"title":"Keyboard shortcuts","description":"Every keyboard shortcut the dashboard registers: the command palette, the assistant, the go-to chords, failure inbox triage, the test lists' search, the keys of the image and element viewers, and Piwi Picker's Runs window.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/reference/keyboard-shortcuts.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/reference/keyboard-shortcuts.html"}],["meta",{"property":"og:title","content":"Keyboard shortcuts | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Every keyboard shortcut the dashboard registers: the command palette, the assistant, the go-to chords, failure inbox triage, the test lists' search, the keys of the image and element viewers, and Piwi Picker's Runs window."}]]},"headers":[],"relativePath":"reference/keyboard-shortcuts.md","filePath":"reference/keyboard-shortcuts.md","lastUpdated":1794573673000}`),a={name:"reference/keyboard-shortcuts.md"};function s(c,e,h,n,i,l){return o(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h1><p>The dashboard&#39;s shortcuts, by where they work. The letter keys never fire while you type in a field.</p><h2 id="anywhere" tabindex="-1">Anywhere <a class="header-anchor" href="#anywhere" aria-label="Permalink to &quot;Anywhere&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Keys</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl</code> + <code>K</code> (<code>⌘</code> + <code>K</code> on macOS)</td><td>Open the command palette: go to a page, search projects, runs and tests, start a <a href="/features/guides.html">guide</a>, or ask the <a href="/features/assistant.html">assistant</a></td></tr><tr><td><code>Ctrl</code> + <code>I</code> (<code>⌘</code> + <code>I</code> on macOS)</td><td>Open the <a href="/features/assistant.html">assistant</a>&#39;s panel; pressed again, put the cursor in its question field, then close it</td></tr><tr><td><code>g</code> then <code>h</code></td><td>Go to Home</td></tr><tr><td><code>g</code> then <code>p</code></td><td>Go to Projects</td></tr><tr><td><code>g</code> then <code>a</code></td><td>Go to Analytics</td></tr><tr><td><code>g</code> then <code>s</code></td><td>Go to Settings</td></tr></tbody></table><h2 id="desktop-app" tabindex="-1">Desktop app <a class="header-anchor" href="#desktop-app" aria-label="Permalink to &quot;Desktop app&quot;">​</a></h2><p>In the <a href="/features/desktop.html">desktop app</a>&#39;s dashboard window. On macOS the app menu holds the first four with <code>⌘</code>, beside the docs, and zoom takes <code>⌘</code> too; Windows and Linux use <code>Ctrl</code>, outside a field you type in.</p><table tabindex="0"><thead><tr><th>Keys</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl</code> + <code>,</code></td><td>Open Settings</td></tr><tr><td><code>Ctrl</code> + <code>O</code></td><td>Pick Playwright archives or bug reports to import</td></tr><tr><td><code>Ctrl</code> + <code>[</code></td><td>Go back</td></tr><tr><td><code>Ctrl</code> + <code>]</code></td><td>Go forward</td></tr><tr><td><code>Ctrl</code> + <code>+</code> / <code>-</code> / <code>0</code></td><td>Zoom in, out, back to 100%</td></tr></tbody></table><h2 id="piwi-picker-s-runs-window" tabindex="-1">Piwi Picker&#39;s Runs window <a class="header-anchor" href="#piwi-picker-s-runs-window" aria-label="Permalink to &quot;Piwi Picker&#39;s Runs window&quot;">​</a></h2><p>In <a href="/features/runs-window.html">Piwi Picker&#39;s Runs window</a>, for the stopped test whose row holds the focus, else the only stopped test shown: a run&#39;s worker tabs show one worker at a time. Step and Finish wait for a stop that is no failure.</p><table tabindex="0"><thead><tr><th>Keys</th><th>Action</th></tr></thead><tbody><tr><td><code>F8</code> or <code>F5</code></td><td>Resume</td></tr><tr><td><code>F10</code></td><td>Step</td></tr><tr><td><code>Shift</code> + <code>F11</code></td><td>Finish</td></tr></tbody></table><p>While <strong>Interact</strong> is on at a <a href="/features/runs-window.html#click-and-type-on-the-view">watched stop</a>, the view takes your pointer: moves, left and right clicks, double and triple clicks as your system counts them, drags, and the wheel once the view has the focus, with <code>Ctrl</code>, <code>Alt</code> and <code>⌘</code> held with a click held in the page too. It takes your keys while it has the focus (a focus ring around it), and a paste, which types the clipboard&#39;s text: characters are typed, named keys (Enter, the arrows, Backspace, Delete, Home, End) pressed, with Shift, and <code>Ctrl</code> (<code>⌘</code> on macOS) with A, Z, Y, Enter and the editing keys. The browser&#39;s other shortcuts, the function keys and <code>Esc</code> stay the window&#39;s: <code>Esc</code> turns <strong>Interact</strong> off, gives the stop back and moves the focus to <strong>Interact</strong>. While a pick or a check runs on the page, <code>Esc</code> goes to the page instead, as its own key. <code>Tab</code> moves the focus on past the view, unless you clicked into it: then <code>Tab</code> and <code>Shift+Tab</code> go to the page too, until <code>Esc</code> turns <strong>Interact</strong> off. Characters an input method composes (Chinese, Japanese, Korean) do not reach the page; paste them instead. The desktop app&#39;s Local runs tray takes the same keys. On a run&#39;s worker tabs, the arrow keys, <code>Home</code> and <code>End</code> move between the workers.</p><h2 id="the-run-shortcut" tabindex="-1">The run shortcut <a class="header-anchor" href="#the-run-shortcut" aria-label="Permalink to &quot;The run shortcut&quot;">​</a></h2><p>Piwi Picker&#39;s run shortcut works from any window. It resumes the stopped tests, else pauses every run, but a run <a href="/guide/concepts.html#hold-failures">nobody attends</a>; Piwi Picker&#39;s toolbar icon shows what it did for a moment. It has no key until you set one: <strong>Set a shortcut</strong>, in the Runs window, opens the browser&#39;s shortcuts page, where you give it a key and, in Chrome and Edge, the <strong>Global</strong> scope. In Firefox, it works while Firefox has the focus.</p><h2 id="assistant-panel" tabindex="-1">Assistant panel <a class="header-anchor" href="#assistant-panel" aria-label="Permalink to &quot;Assistant panel&quot;">​</a></h2><p>In the <a href="/features/assistant.html#asking-a-question">assistant</a>&#39;s question field:</p><table tabindex="0"><thead><tr><th>Keys</th><th>Action</th></tr></thead><tbody><tr><td><code>Enter</code></td><td>Ask; <code>Shift</code> + <code>Enter</code> starts a new line</td></tr><tr><td><code>↑</code></td><td>On the first line, bring back your previous question, from any of your conversations</td></tr><tr><td><code>↓</code></td><td>On the last line, go back toward what you were typing</td></tr><tr><td><code>→</code></td><td>In the empty field, take the question it shows greyed: the one the last answer suggests, or the page&#39;s</td></tr><tr><td><code>Esc</code></td><td>Stop the answer being written</td></tr></tbody></table><h2 id="failure-inbox" tabindex="-1">Failure inbox <a class="header-anchor" href="#failure-inbox" aria-label="Permalink to &quot;Failure inbox&quot;">​</a></h2><p>On the <a href="/features/failure-clusters.html#triage-from-the-row-or-the-keyboard">failure inbox</a>, the keys act on the selected row. The triage actions need the Maintainer role or above on the project.</p><table tabindex="0"><thead><tr><th>Keys</th><th>Action</th></tr></thead><tbody><tr><td><code>j</code> / <code>k</code></td><td>Select the next / previous row</td></tr><tr><td><code>Shift</code> + <code>j</code> / <code>k</code></td><td>Extend the selection down / up</td></tr><tr><td><code>x</code></td><td>Add the row to the selection, for the bulk bar</td></tr><tr><td><code>Esc</code></td><td>Clear the selection</td></tr><tr><td><code>o</code></td><td>Open the cluster</td></tr><tr><td><code>r</code></td><td>Resolve</td></tr><tr><td><code>i</code></td><td>Ignore</td></tr><tr><td><code>q</code></td><td>Quarantine the cluster&#39;s tests</td></tr><tr><td><code>a</code></td><td>Assign</td></tr><tr><td><code>s</code></td><td>Snooze</td></tr><tr><td><code>l</code></td><td>Link a known issue</td></tr><tr><td><code>c</code></td><td>Create an issue in the connected tracker, when the cluster has none</td></tr></tbody></table><h2 id="test-lists" tabindex="-1">Test lists <a class="header-anchor" href="#test-lists" aria-label="Permalink to &quot;Test lists&quot;">​</a></h2><p>On a run&#39;s and a project&#39;s <strong>Tests</strong> tab (<a href="/reference/test-search.html">test search</a>):</p><table tabindex="0"><thead><tr><th>Keys</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl</code> + <code>F</code> (<code>⌘</code> + <code>F</code> on macOS)</td><td>Focus the search box; pressed again there, open the browser&#39;s find</td></tr><tr><td><code>↓</code> / <code>↑</code></td><td>Move through the search suggestions</td></tr><tr><td><code>Enter</code> / <code>Tab</code></td><td>Take the highlighted suggestion</td></tr><tr><td><code>Esc</code></td><td>Close the suggestions</td></tr></tbody></table><h2 id="screenshot-viewer" tabindex="-1">Screenshot viewer <a class="header-anchor" href="#screenshot-viewer" aria-label="Permalink to &quot;Screenshot viewer&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Keys</th><th>Action</th></tr></thead><tbody><tr><td><code>←</code> / <code>→</code></td><td>Previous / next image</td></tr><tr><td><code>Esc</code></td><td>Zoom out, then close</td></tr></tbody></table><h2 id="element-picker" tabindex="-1">Element picker <a class="header-anchor" href="#element-picker" aria-label="Permalink to &quot;Element picker&quot;">​</a></h2><p>When you <a href="/features/locator-healing.html">pick a replacement locator</a> on a captured page:</p><table tabindex="0"><thead><tr><th>Keys</th><th>Action</th></tr></thead><tbody><tr><td><code>↑</code></td><td>Select the parent of the highlighted element</td></tr><tr><td><code>↓</code></td><td>Go back down to the child</td></tr><tr><td><code>Esc</code></td><td>Skip picking, without choosing an element</td></tr></tbody></table><h2 id="permission-grid" tabindex="-1">Permission grid <a class="header-anchor" href="#permission-grid" aria-label="Permalink to &quot;Permission grid&quot;">​</a></h2><p>On the <a href="/operate/project-access.html#permission-grid">permission grid</a>, the arrow keys move between cells, and <code>Home</code> / <code>End</code> jump to the first / last column of the row. <code>Space</code> or <code>Enter</code> opens the focused cell&#39;s role menu, and <code>Esc</code> closes it.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/features/ui-overview.html">UI overview</a>: the pages these keys move between</li><li><a href="/reference/test-search.html">Test search</a>: the language of the Tests tabs&#39; search box</li><li><a href="/features/failure-clusters.html">Failure clusters &amp; the inbox</a>: the triage actions</li><li><a href="/operate/project-access.html#permission-grid">Access, roles and groups</a>: the permission grid</li></ul>',31)])])}const b=t(a,[["render",s]]);export{p as __pageData,b as default};
